package io.github.gamesbyian.chunks.rpc

import java.net.URI
import kotlinx.coroutines.delay
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * Real disposable rTorrent through nginx HTTP Basic authentication, rather
 * than the unprotected /RPC2 fixture. Only CI's loopback /AUTHRPC is allowed.
 * Per-run synthetic credentials are generated by the disposable workflow.
 * No protected Seedhost, user media, tracker, or arbitrary host is accessed.
 */
class RTorrentDisposableAuthenticatedTest {
    private data class Fixture(val url: String, val user: String, val pass: String, val place: String)

    private fun fixture(): Fixture {
        val url = System.getenv("CHUNKS_DISPOSABLE_AUTH_URL").orEmpty()
        assumeTrue("Explicit disposable auth fixture is required", url.isNotEmpty())
        val uri = URI(url)
        require(uri.scheme == "http" && uri.host == "127.0.0.1" &&
            uri.port == 18080 && uri.rawPath == "/AUTHRPC" &&
            uri.userInfo == null && uri.rawQuery == null && uri.rawFragment == null) {
            "Refusing an authenticated real-server test outside exact loopback /AUTHRPC"
        }
        val user = System.getenv("CHUNKS_DISPOSABLE_AUTH_USER").orEmpty()
        val pass = System.getenv("CHUNKS_DISPOSABLE_AUTH_PASS").orEmpty()
        require(user == "chunks-disposable" && pass.length >= 32) {
            "Missing per-run synthetic disposable Basic credentials"
        }
        val place = System.getenv("CHUNKS_DISPOSABLE_TARGET_DIR").orEmpty()
        require(place.startsWith("/") && place.contains("chunks-data")) {
            "Missing isolated disposable rTorrent data root"
        }
        return Fixture(url, user, pass, place)
    }

    // A distinct untracked single-file fixture; no shared ordinary test hash
    // or remote media. No tracker, DNS name, or peer destination is included.
    private val metainfo = (
        "d4:infod6:lengthi5e4:name12:safeauth.bin12:piece lengthi16384e6:pieces20:" +
        "01234567890123456789ee"
    ).toByteArray(Charsets.UTF_8)
    private val hash by lazy { TorrentMetainfoReader.preview(metainfo).infoHashV1 }

    @Test fun wrongPrincipalCannotPassAuthenticatedDiscovery() = runBlocking {
        val f = fixture()
        for ((user, password) in listOf(
            f.user + "-wrong" to f.pass,
            f.user to (f.pass + "-wrong")
        )) {
            val refused = try {
                RemoteSmartConnect.connect(f.url, user, password) { credentials ->
                    val remote = RTorrentRemote(credentials)
                    remote.version()
                    remote.listTransfers("main")
                    requireRemoteConnectIdentityEvidence(credentials, remote)
                }
                fail("A wrong rTorrent account/password was admitted")
                null
            } catch (failure: RemoteSmartConnect.ConnectionFailed) { failure }
            assertEquals("A protected real endpoint must reject a wrong principal",
                RemoteSmartConnect.Category.AUTH, refused?.category)
            assertEquals("An exact path cannot fan out onto another tenant",
                1, refused?.tested)
        }
    }

    @Test fun acceptedChallengeBindsOneShotRealLifecycleToExactHashAndPlace() = runBlocking {
        val f = fixture()
        val verified = RemoteSmartConnect.connect(f.url, f.user, f.pass) { credentials ->
            val remote = RTorrentRemote(credentials)
            val version = remote.version()
            val list = remote.listTransfers("main")
            requireRemoteConnectIdentityEvidence(credentials, remote)
            Triple(remote, version, list)
        }
        assertEquals(f.url, verified.credentials.endpoint)
        assertEquals(f.user, verified.credentials.username)
        assertEquals(1, verified.attempts)
        val remote = verified.response.first
        assertTrue("Actual engine version required", verified.response.second.isNotBlank())
        assertEquals(RemoteReadAuthEvidence.READ_CHALLENGE_ACCEPTED,
            remote.readAuthenticationEvidence())
        val before = verified.response.third.map { it.hash.uppercase() }.toSet()
        assertFalse("Fixture hash must not exist on the disposable engine", hash.uppercase() in before)

        // Exactly one authenticated stopped Add, with no auto-Start or replay.
        val submitted = remote.loadStoppedTorrentBytes(metainfo, f.place)
        assertTrue("Unexpected protected Add outcome: $submitted",
            submitted is RemoteAddOutcome.VerifiedStopped ||
                submitted is RemoteAddOutcome.PendingVerification)
        suspend fun observed(): RemoteTransfer? =
            remote.listTransfers("main").singleOrNull { it.hash.equals(hash, true) }
        var added: RemoteTransfer? = null
        for (attempt in 1..15) {
            added = observed()
            if (added != null) break
            delay(400)
        }
        val target = requireNotNull(added) { "Exact authenticated Add never reached real rTorrent" }
        assertFalse("Reviewed Add must remain stopped", target.started)
        assertEquals("safeauth.bin", target.name)
        assertEquals("Single-file Add must use reviewed parent", f.place, target.directory)

        val start = remote.setStarted(hash, true)
        assertTrue("Authenticated Start must not lose ACK: $start",
            start is LifecycleOutcome.Verified || start is LifecycleOutcome.Pending)
        var started = false
        for (attempt in 1..15) {
            started = observed()?.started == true
            if (started) break
            delay(400)
        }
        assertTrue("Real authenticated job did not enter started state", started)

        val stop = remote.setStarted(hash, false)
        assertTrue("Authenticated Stop must not lose ACK: $stop",
            stop is LifecycleOutcome.Verified || stop is LifecycleOutcome.Pending)
        var stopped = false
        for (attempt in 1..15) {
            stopped = observed()?.started == false
            if (stopped) break
            delay(400)
        }
        assertTrue("Real authenticated job remained started", stopped)

        val file = remote.listFiles(hash).single()
        assertEquals("safeauth.bin", file.path)
        val desired = if (file.priority == 2) 0 else 2
        val priority = remote.setFilePriority(
            hash, 0, file.path, file.sizeBytes, file.priority, desired)
        assertTrue("Protected file priority mutation remains inconclusive: $priority",
            priority is FilePriorityOutcome.Verified ||
                priority is FilePriorityOutcome.PendingVerification)
        assertEquals("Real rTorrent did not apply protected file priority", desired,
            remote.listFiles(hash).single().priority)

        // Session-only d.erase; never invoke ruTorrent erasedata or touch the
        // fixture payload. Independently check every unrelated original hash.
        val removal = remote.eraseFromSession(hash, target.name, target.directory)
        assertTrue("Protected exact-hash session removal was uncertain: $removal",
            removal is SessionEraseOutcome.VerifiedRemoved ||
                removal is SessionEraseOutcome.PendingRemoval)
        var absent = false
        for (attempt in 1..15) {
            absent = observed() == null
            if (absent) break
            delay(400)
        }
        assertTrue("Original job remains in real session's main view", absent)
        assertEquals("Do not drop or modify any unrelated disposable job identity",
            before, remote.listTransfers("main").map { it.hash.uppercase() }.toSet())
    }
}
